class UnsafeCounter {
  private int c = 0;
  void inc() { c++; } // read-modify-write: 3 steps, not 1
  int get() { return c; }
}
// Two threads x 100_000 inc() each routinely return ~130_000-190_000,
// not 200_000. Interleaving: T1 reads 41, T2 reads 41, both write 42.
// One increment is lost. No exception, no crash — just a wrong number.

class SafeCounter {
  private int c = 0;
  synchronized void inc() { c++; }
  synchronized int get() { return c; }
  // Same monitor (this) on both sides = exclusion + visibility.
  // Remove synchronized from get() and a reader can spin on a stale cached copy.
}

class CounterBlock {
  private int c = 0;
  private final Object lock = new Object();
  void inc() {
    // validate outside, mutate inside: shrink the critical section
    synchronized (lock) { c++; }
  }
  int get() {
    synchronized (lock) { return c; }
  }
}

class CounterStatic {
  private static int c = 0;
  static synchronized void inc() { c++; }
  // locks CounterStatic.class — does NOT exclude instance locks.
  // Mixing static and instance synchronization on shared state is a bug.
}

class GuardedQueue<T> {
  private final Queue<T> q = new ArrayDeque<>();
  private final Object lock = new Object();

  void put(T x) {
    synchronized (lock) {
      q.add(x);
      lock.notifyAll(); // signal AFTER state change, same monitor
    }
  }
  T take() throws InterruptedException {
    synchronized (lock) {
      while (q.isEmpty()) lock.wait(); // loop: spurious wakeups are real
      return q.remove();
    }
  }
}
// Modern alternative when you need timeouts or multiple conditions:
// ReentrantLock + Condition lets one condition mean "not-full" and
// another mean "not-empty" instead of waking everyone with notifyAll().
// Trade-off: you must unlock in finally or you wedge the queue forever.
